package com.hrflow.platform.user;
import com.hrflow.platform.common.ApiModels.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/users") @RequiredArgsConstructor @PreAuthorize("hasRole('ADMIN')") public class UserController {private final UserService service;
 @GetMapping Page<UserView> list(@RequestParam(required=false)String search,@PageableDefault(sort="email")Pageable p){return service.list(search,p);}@GetMapping("/{id}")UserView get(@PathVariable Long id){return service.get(id);}@PatchMapping("/{id}/role")UserView role(@PathVariable Long id,@Valid @RequestBody RoleUpdate in){return service.role(id,in);}@PatchMapping("/{id}/status")UserView status(@PathVariable Long id,@Valid @RequestBody StatusUpdate in){return service.status(id,in);}}
